package com.example.securevault.data.entity

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.PrimaryKey
import com.example.securevault.model.Note
import com.example.securevault.model.PrivateNote
import com.example.securevault.model.PublicNote

/**
 * Database Schema 2: Set of Notes.
 * Persists both Public and Private notes.
 * The primary key ID is auto-generated by the database engine (SQLite / Room).
 */
@Entity(tableName = "notes")
data class NoteEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,

    @ColumnInfo(name = "title")
    val title: String,

    @ColumnInfo(name = "content")
    val content: String,

    @ColumnInfo(name = "is_private")
    val isPrivate: Boolean,

    @ColumnInfo(name = "password")
    val password: String? = null
) {
    /**
     * Converts this database entity into its corresponding domain Note model
     * (either PublicNote or PrivateNote).
     */
    fun toDomain(): Note {
        return if (isPrivate) {
            PrivateNote(
                id = id,
                title = title,
                content = content,
                password = password ?: ""
            )
        } else {
            PublicNote(
                id = id,
                title = title,
                content = content
            )
        }
    }

    companion object {
        /**
         * Creates a NoteEntity from a domain Note object.
         */
        fun fromDomain(note: Note): NoteEntity {
            return when (note) {
                is PrivateNote -> NoteEntity(
                    id = note.id,
                    title = note.title,
                    content = note.content,
                    isPrivate = true,
                    password = note.password
                )
                is PublicNote -> NoteEntity(
                    id = note.id,
                    title = note.title,
                    content = note.content,
                    isPrivate = false,
                    password = null
                )
                else -> NoteEntity(
                    id = note.id,
                    title = note.title,
                    content = note.content,
                    isPrivate = note.isPrivate(),
                    password = null
                )
            }
        }
    }
}
